/// <summary>
/// PaffH 04.06.21
/// dialog for deleting open notifications
/// </summary>
class NDXDeleteNotificationsDlg extends Runbase
{
    DialogField dlgFieldUser;
    DialogField dlgFieldUtcDateTimeFrom;
    DialogField dlgFieldUtcDateTimeTo;
    UserId user;
    utcdatetime utcDateTimeFrom;
    utcdatetime utcDateTimeTo;
    date dateFrom;
    date dateTo;

}

Method.Source:
	/// <summary>
    /// PaffH 05.06.21
    /// delete open notifications for a time period
    /// </summary>
	public void run()
    {
        new SystemNotificationsManager().DeleteNotificationsFromRange(utcDateTimeFrom, utcDateTimeTo, user);
    }

/// <summary>
/// PaffH 05.06.21
/// Runs the class with the specified arguments.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    NDXDeleteNotificationsDlg nDXDeleteNotificationsDlg = new NDXDeleteNotificationsDlg();

    if (nDXDeleteNotificationsDlg.prompt())
    {
        nDXDeleteNotificationsDlg.runOperation();
    }
}

/// <summary>
/// PaffH 05.06.21
/// </summary>
/// <returns>Object</returns>
public Object dialog()
{
    Dialog dialog = super();
    dialog.caption("@NDX:NDXDeleteOpenNotifications");
    dlgFieldUser = dialog.addFieldValue(extendedTypeStr(UserId), user, "@NDX:NDXForUser");
    dialog.addGroup("@NDX:NDXDeletionPeriod");
    dlgFieldUtcDateTimeFrom = dialog.addFieldValue(identifierStr(utcdatetime), utcDateTimeFrom,"@NDX:NDXFrom");
    dlgFieldUtcDateTimeTo = dialog.addFieldValue(identifierStr(utcdateTime), utcDateTimeTo,"@NDX:NDXTo");
    return dialog;
}

/// <summary>
/// PaffH 05.06.21
/// </summary>
protected void new()
{
    super();
    user = curUserId();
    utcDateTimeFrom = DateTimeUtil::utcNow();
    utcDateTimeTo = DateTimeUtil::utcNow();
}

/// <summary>
/// PaffH 05.06.21
/// </summary>
/// <returns>boolean</returns>
public boolean getFromDialog()
{

    user = dlgFieldUser.value();
    utcDateTimeFrom = dlgFieldUtcDateTimeFrom.value();
    utcDateTimeTo = dlgFieldUtcDateTimeTo.value();

    return super();
}

/// <summary>
/// PaffH 28.09.21
/// BP method to override
/// </summary>
/// <returns>boolean</returns>
protected boolean canRunInNewSession()
{
    boolean ret;

    ret = super();

    return ret;
}
